const start = Date.now();
$execution.customData.set('engine_start', start);
console.log('[NEXO Intelligence] Engine iniciado - ' + new Date().toISOString());
return [{ json: { started_at: new Date().toISOString(), ts: start } }];

const campaigns = $input.all();
if (!campaigns || campaigns.length === 0) {
  console.log('[NEXO Intelligence] Nenhuma campanha ativa.');
  return [];
}
console.log('[NEXO Intelligence] Campanhas ativas: ' + campaigns.length);
$execution.customData.set('total_campaigns', campaigns.length);
return campaigns.map(c => ({ json: c.json }));

// === NORMALIZAR === unifica formato das menções (24h e baseline 7d), parseia metadata,
// padroniza sentimento e extrai campos derivados. Responsabilidade única.
const campaign = $('Loop por Campanha').item.json;
const raw24 = $('Buscar Menções 24h').all().map(i => i.json);
const raw7d = $('Buscar Menções 7d').all().map(i => i.json);
const alerts = $('Buscar Alertas 24h').all().map(i => i.json);
const entities = $('Buscar Entidades Monitoradas').all().map(i => i.json);
const prevSnap = $('Buscar Snapshot Anterior').all().map(i => i.json);
const prev_snapshot = prevSnap.length ? prevSnap[0] : null;

function parseMeta(m){
  if (!m) return {};
  if (typeof m === 'string') { try { return JSON.parse(m); } catch(e){ return {}; } }
  return m;
}
function normSent(s){
  s = (s || 'neutral').toString().toLowerCase();
  if (s.indexOf('pos') === 0) return 'positive';
  if (s.indexOf('neg') === 0) return 'negative';
  return 'neutral';
}
// Provedores genéricos (nome da API, não do veículo) -> preferimos o domínio da URL.
const GENERIC = ['gnews', 'serpapi', 'newsapi', 'google news', 'unknown', ''];
function domainOf(url){
  if (!url) return '';
  const m = url.toString().match(/^https?:\/\/(?:www\.)?([^\/]+)/i);
  return m ? m[1].toLowerCase() : '';
}
function normalize(m){
  const meta = parseMeta(m.metadata);
  const dom = domainOf(m.url);
  const declared = (meta.source_name || '').toString().trim();
  const source_name = (GENERIC.indexOf(declared.toLowerCase()) < 0 && declared) ? declared : (dom || m.source || 'unknown');
  return {
    id: m.id,
    entity_id: m.entity_id || null,
    entity_name: m.entity_name || meta.entity_name || null,
    entity_type: m.entity_type || meta.entity_type || null,
    source: (m.source || 'unknown').toString().toLowerCase(),
    source_name: source_name,
    domain: dom,
    title: m.title || '',
    sentiment: normSent(m.sentiment),
    url: m.url || '',
    relevance_score: Number(meta.relevance_score) || 0,
    impact_score: Number(meta.impact_score) || 0,
    criticidade: (meta.criticidade || 'low').toString().toLowerCase(),
    temas: Array.isArray(meta.principais_temas) ? meta.principais_temas : [],
    mencao_adversario: !!meta.mencao_adversario,
    summary: meta.summary || '',
    published_at: m.published_at || m.created_at,
    created_at: m.created_at
  };
}
const mentions = raw24.map(normalize);
const mentions7d = raw7d.map(normalize);
const no_data = mentions.length === 0;
console.log('[NEXO Intelligence] ' + campaign.name + ' | 24h=' + mentions.length + ' 7d=' + mentions7d.length + ' alertas=' + alerts.length);
return [{ json: { campaign, mentions, mentions7d, alerts, entities, prev_snapshot, no_data } }];

const d = $input.first().json;
console.log('[NEXO Intelligence] Sem dados para: ' + (d.campaign && d.campaign.name));
return [{ json: { status: 'skipped', campaign: d.campaign && d.campaign.name } }];

// === DEDUPLICAR === remove menções repetidas (url+entity_id) mantendo a mais completa.
const d = $input.first().json;
function dedupe(list){
  const map = new Map();
  const score = x => (x.summary ? 2 : 0) + (x.temas.length ? 1 : 0) + (x.impact_score || 0);
  for (const m of list){
    const key = (m.entity_id || '') + '|' + (m.url || m.id);
    const prev = map.get(key);
    if (!prev || score(m) > score(prev)) map.set(key, m);
  }
  return Array.from(map.values());
}
const mentions = dedupe(d.mentions);
const mentions7d = dedupe(d.mentions7d);
console.log('[NEXO Intelligence] Dedupe 24h: ' + d.mentions.length + ' -> ' + mentions.length);
return [{ json: Object.assign({}, d, { mentions, mentions7d }) }];

// === AGRUPAR / CLUSTERIZAR === agrupa por tema, fonte e entidade (reduz volume ao LLM).
const d = $input.first().json;
const ms = d.mentions;
const themeMap = {};
for (const m of ms){
  for (const t of m.temas){
    if (!themeMap[t]) themeMap[t] = { tema: t, count: 0, positive: 0, neutral: 0, negative: 0, impact_sum: 0 };
    themeMap[t].count++; themeMap[t][m.sentiment]++; themeMap[t].impact_sum += m.impact_score;
  }
}
const clusters_themes = Object.values(themeMap)
  .map(t => ({ tema: t.tema, count: t.count, positive: t.positive, neutral: t.neutral, negative: t.negative, avg_impact: t.count ? Number((t.impact_sum / t.count).toFixed(2)) : 0 }))
  .sort((a, b) => b.count - a.count);

const srcMap = {};
for (const m of ms) srcMap[m.source_name] = (srcMap[m.source_name] || 0) + 1;
const clusters_sources = Object.keys(srcMap).map(k => ({ source: k, count: srcMap[k] })).sort((a, b) => b.count - a.count);

const entMap = {};
for (const m of ms){
  const k = m.entity_id || m.entity_name || 'unknown';
  if (!entMap[k]) entMap[k] = { entity_id: m.entity_id, entity_name: m.entity_name, entity_type: m.entity_type, count: 0, positive: 0, neutral: 0, negative: 0 };
  entMap[k].count++; entMap[k][m.sentiment]++;
}
const clusters_entities = Object.values(entMap).sort((a, b) => b.count - a.count);
console.log('[NEXO Intelligence] Clusters: temas=' + clusters_themes.length + ' fontes=' + clusters_sources.length + ' entidades=' + clusters_entities.length);
return [{ json: Object.assign({}, d, { clusters_themes, clusters_sources, clusters_entities }) }];

// === CALCULAR MÉTRICAS (estatística pura, sem IA) ===
const d = $input.first().json;
const ms = d.mentions;
const total = ms.length;
const by = s => ms.filter(m => m.sentiment === s).length;
const sentiment_count = { positive: by('positive'), neutral: by('neutral'), negative: by('negative') };
const ratio = n => total ? Number((n / total * 100).toFixed(1)) : 0;
const sentiment_ratio = { positive: ratio(sentiment_count.positive), neutral: ratio(sentiment_count.neutral), negative: ratio(sentiment_count.negative) };
const avg = key => total ? Number((ms.reduce((s, m) => s + (m[key] || 0), 0) / total).toFixed(3)) : 0;

const news = ms.filter(m => m.source === 'news');
const social = ms.filter(m => ['facebook', 'instagram', 'twitter', 'social'].indexOf(m.source) >= 0);
const distinct_sources = new Set(ms.map(m => m.source_name)).size;
const distinct_entities = new Set(ms.map(m => m.entity_id || m.entity_name)).size;

const NATIONAL = ['g1', 'globo', 'folha', 'estadao', 'estadão', 'uol', 'cnn', 'metropoles', 'metrópoles', 'poder360', 'veja', 'terra', 'r7', 'band', 'valor', 'antagonista'];
const isNational = sn => { const s = (sn || '').toLowerCase(); return NATIONAL.some(n => s.indexOf(n) >= 0); };
const national_count = new Set(news.filter(m => isNational(m.source_name)).map(m => m.source_name)).size;

const crit = lvl => ms.filter(m => m.criticidade === lvl).length;
const criticidade_count = { low: crit('low'), medium: crit('medium'), high: crit('high'), critical: crit('critical') };

const adversary = ms.filter(m => m.entity_type === 'opponent');
const adversary_negative = adversary.filter(m => m.sentiment === 'negative').length;

const statistics = {
  total_mentions: total,
  sentiment_count, sentiment_ratio,
  avg_impact: avg('impact_score'), avg_relevance: avg('relevance_score'),
  news_count: news.length, social_count: social.length,
  distinct_sources, distinct_entities, national_count,
  criticidade_count,
  adversary_count: adversary.length, adversary_negative,
  positive_high_impact: ms.filter(m => m.sentiment === 'positive' && m.impact_score >= 0.6).length,
  negative_high_impact: ms.filter(m => m.sentiment === 'negative' && m.impact_score >= 0.6).length
};
const top_news = news
  .map(m => ({ title: m.title, source_name: m.source_name, sentiment: m.sentiment, impact_score: m.impact_score, relevance_score: m.relevance_score, url: m.url, entity_name: m.entity_name, published_at: m.published_at, summary: m.summary }))
  .sort((a, b) => (b.impact_score + b.relevance_score) - (a.impact_score + a.relevance_score))
  .slice(0, 10);
console.log('[NEXO Intelligence] Métricas: total=' + total + ' neg%=' + sentiment_ratio.negative);
return [{ json: Object.assign({}, d, { statistics, top_news }) }];

// === CALCULAR TENDÊNCIAS === janela 0-24h vs 24-48h (do baseline 7d) + snapshot anterior.
const d = $input.first().json;
const now = Date.now();
const H = 3600 * 1000;
const inWindow = (m, fromH, toH) => { const t = new Date(m.created_at).getTime(); return t >= now - toH * H && t < now - fromH * H; };
const cur = d.mentions;
const prev = d.mentions7d.filter(m => inWindow(m, 24, 48));

const sr = list => { const n = list.length; return { n, neg: n ? list.filter(m => m.sentiment === 'negative').length / n : 0, pos: n ? list.filter(m => m.sentiment === 'positive').length / n : 0 }; };
const c = sr(cur), p = sr(prev);
const pct = (a, b) => b > 0 ? Number((((a - b) / b) * 100).toFixed(1)) : (a > 0 ? 100 : 0);
const volume_change_pct = pct(c.n, p.n);
const negative_change_pp = Number(((c.neg - p.neg) * 100).toFixed(1));
const positive_change_pp = Number(((c.pos - p.pos) * 100).toFixed(1));

const themeCount = list => { const o = {}; for (const m of list){ for (const t of m.temas){ o[t] = (o[t] || 0) + 1; } } return o; };
const curT = themeCount(cur), prevT = themeCount(prev);
const tKeys = new Set(Object.keys(curT).concat(Object.keys(prevT)));
const tDelta = []; tKeys.forEach(t => tDelta.push({ tema: t, now: curT[t] || 0, prev: prevT[t] || 0, delta: (curT[t] || 0) - (prevT[t] || 0) }));
const themes_rising = tDelta.filter(x => x.delta > 0).sort((a, b) => b.delta - a.delta).slice(0, 8);
const themes_falling = tDelta.filter(x => x.delta < 0).sort((a, b) => a.delta - b.delta).slice(0, 8);

const entCount = list => { const o = {}; for (const m of list){ const k = m.entity_name || m.entity_id; if (k) o[k] = (o[k] || 0) + 1; } return o; };
const curE = entCount(cur), prevE = entCount(prev);
const eKeys = new Set(Object.keys(curE).concat(Object.keys(prevE)));
const eDelta = []; eKeys.forEach(k => eDelta.push({ entity: k, now: curE[k] || 0, prev: prevE[k] || 0, delta: (curE[k] || 0) - (prevE[k] || 0) }));
const entities_rising = eDelta.filter(x => x.delta > 0).sort((a, b) => b.delta - a.delta).slice(0, 5);
const entities_fading = eDelta.filter(x => x.delta < 0).sort((a, b) => a.delta - b.delta).slice(0, 5);

let sentiment_trend = 'stable';
if (negative_change_pp >= 10) sentiment_trend = 'growing_negative';
else if (positive_change_pp >= 10) sentiment_trend = 'growing_positive';
if (c.neg > 0.5 && negative_change_pp > 0) sentiment_trend = 'critical';

const has_baseline = prev.length > 0 || !!d.prev_snapshot;
const trend_analysis = { has_baseline, window: '24h_vs_prev_24h', volume_change_pct, negative_change_pp, positive_change_pp, sentiment_trend, themes_rising, themes_falling, entities_rising, entities_fading };
console.log('[NEXO Intelligence] Tendência: vol=' + volume_change_pct + '% neg=' + negative_change_pp + 'pp trend=' + sentiment_trend);
return [{ json: Object.assign({}, d, { trend_analysis }) }];

// === STRATEGIC METRICS === 11 indicadores 0-100, determinísticos. Fórmulas documentadas inline.
const BENCH_VOLUME = 50;   // menções/24h consideradas "alto volume"
const BENCH_SOURCES = 10;  // diversidade de fontes
const BENCH_NATIONAL = 5;  // portais nacionais distintos
const BENCH_ENTITIES = 5;  // dispersão de entidades

const d = $input.first().json;
const s = d.statistics, tr = d.trend_analysis, prev = d.prev_snapshot;
const total = s.total_mentions || 0;
const clamp = (x, lo, hi) => Math.max(lo === undefined ? 0 : lo, Math.min(hi === undefined ? 1 : hi, x));
const pct100 = x => Math.round(clamp(x) * 100);

const negRatio = total ? s.sentiment_count.negative / total : 0;
const posRatio = total ? s.sentiment_count.positive / total : 0;
const cw = { low: 0.15, medium: 0.4, high: 0.7, critical: 1 };
const cc = s.criticidade_count;
const critTotal = cc.low + cc.medium + cc.high + cc.critical;
const critSeverity = critTotal ? (cc.low * cw.low + cc.medium * cw.medium + cc.high * cw.high + cc.critical * cw.critical) / critTotal : 0;

const volumeFactor = clamp(total / BENCH_VOLUME);
const sourceDiversity = clamp(s.distinct_sources / BENCH_SOURCES);
const nationalFactor = clamp(s.national_count / BENCH_NATIONAL);
const entitySpread = clamp(s.distinct_entities / BENCH_ENTITIES);
const newsVolumeFactor = clamp(s.news_count / BENCH_VOLUME);

const adversaryShare = total ? s.adversary_count / total : 0;
const adversaryNegRatio = s.adversary_count ? s.adversary_negative / s.adversary_count : 0;

const volDelta = clamp((tr.volume_change_pct || 0) / 100, -1, 1);
const negDeltaPP = (tr.negative_change_pp || 0) / 100;
const posDeltaPP = (tr.positive_change_pp || 0) / 100;
const topTheme = (d.clusters_themes && d.clusters_themes[0]) ? d.clusters_themes[0].count : 0;
const topThemeShare = total ? clamp(topTheme / total) : 0;

// 1. Risk: negatividade + criticidade + impacto médio
const risk_score = pct100(0.5 * negRatio + 0.3 * critSeverity + 0.2 * s.avg_impact);
// 2. Crisis: pico agudo negativo de alto impacto + piora recente
const crisis_score = pct100(0.4 * (cc.critical / Math.max(total, 1)) + 0.35 * negRatio * s.avg_impact + 0.25 * clamp(negDeltaPP * 2, 0, 1));
// 3. Popularity: predominância positiva ponderada por volume
const popularity_score = pct100(0.6 * posRatio + 0.2 * (1 - negRatio) + 0.2 * volumeFactor);
// 4. Momentum: 50=estável; sobe com volume e sentimento positivo, cai com negativo
const momentum_score = pct100(0.5 + 0.5 * clamp((volDelta + posDeltaPP - negDeltaPP) / 2, -1, 1));
// 5. Media: intensidade/alcance de imprensa
const media_score = pct100(0.4 * newsVolumeFactor + 0.3 * sourceDiversity + 0.3 * nationalFactor);
// 6. Opportunity: aberturas favoráveis
const opportunity_score = pct100(0.5 * posRatio * Math.max(s.avg_relevance, 0.3) + 0.5 * (s.positive_high_impact / Math.max(total, 1)));
// 7. Attack: agressão adversária
const attack_score = pct100(0.5 * adversaryShare + 0.5 * adversaryNegRatio);
// 8. Narrative: controle narrativo (dominância de tema + alinhamento positivo)
const narrative_score = pct100(0.5 * topThemeShare + 0.5 * posRatio);
// 9. Trust: reputação (inverso da negatividade ponderada por criticidade)
const trust_score = pct100(1 - (0.6 * negRatio + 0.4 * critSeverity));
// 10. Influence: alcance (volume + diversidade + dispersão de entidades)
const influence_score = pct100(0.4 * volumeFactor + 0.3 * sourceDiversity + 0.3 * entitySpread);
// 11. Overall: posição estratégica composta (maior = melhor)
const overall_intelligence_score = pct100(
  0.28 * (1 - risk_score / 100) +
  0.18 * (popularity_score / 100) +
  0.14 * (trust_score / 100) +
  0.12 * (media_score / 100) +
  0.10 * (opportunity_score / 100) +
  0.10 * (momentum_score / 100) +
  0.08 * (1 - attack_score / 100)
);

const strategic_metrics = {
  risk_score, crisis_score, popularity_score, momentum_score, media_score,
  opportunity_score, attack_score, narrative_score, trust_score, influence_score,
  overall_intelligence_score,
  basis: { total, negRatio: Number(negRatio.toFixed(3)), posRatio: Number(posRatio.toFixed(3)), critSeverity: Number(critSeverity.toFixed(3)), volumeFactor: Number(volumeFactor.toFixed(3)) }
};
if (prev && typeof prev.overall_score === 'number') strategic_metrics.overall_delta = overall_intelligence_score - prev.overall_score;
console.log('[NEXO Intelligence] Scores: risk=' + risk_score + ' crisis=' + crisis_score + ' overall=' + overall_intelligence_score);
return [{ json: Object.assign({}, d, { strategic_metrics }) }];

// === CONSTRUIR CONTEXTO ESTRATÉGICO === objeto estruturado para o LLM interpretar.
const d = $input.first().json;
const c = d.campaign;
const strategic_context = {
  campaign_summary: { name: c.name, candidate: c.candidate_name || null, client: c.client_name || null, region: c.target_region || null, period: '24h' },
  statistics: d.statistics,
  strategic_metrics: d.strategic_metrics,
  trend_analysis: d.trend_analysis,
  top_topics: d.clusters_themes.slice(0, 10),
  top_sources: d.clusters_sources.slice(0, 8),
  top_entities: d.clusters_entities.slice(0, 10),
  top_news: d.top_news.slice(0, 8),
  recent_alerts: (d.alerts || []).slice(0, 10).map(a => ({ title: a.title, description: a.description, severity: a.severity }))
};
return [{ json: Object.assign({}, d, { strategic_context }) }];

// === INTERPRETAR JSON (parse + repair + fallback determinístico) ===
const d = $('Construir Prompt').first().json;
const aiItem = $('LLM - Interpretação').first();
const raw = aiItem && aiItem.json ? (aiItem.json.text || aiItem.json.output || (aiItem.json.message && aiItem.json.message.content) || (aiItem.json.choices && aiItem.json.choices[0] && aiItem.json.choices[0].message.content) || '') : '';

function tryParse(txt){
  if (!txt) return null;
  let t = txt.replace(/```json/gi, '').replace(/```/g, '').trim();
  try { return JSON.parse(t); } catch(e){}
  const i = t.indexOf('{'), j = t.lastIndexOf('}');
  if (i >= 0 && j > i){ try { return JSON.parse(t.slice(i, j + 1)); } catch(e){} }
  try { return JSON.parse(t.replace(/,\s*([}\]])/g, '$1')); } catch(e){}
  return null;
}
const EMPTY = { summary: '', sentiment_analysis: { overview: '', trend: 'stable', critical_points: [] }, themes_rising: [], themes_falling: [], risks: [], opportunities: [], adversary_movements: [], narrative_changes: [], crisis_alerts: [], insights: [], recommendations: [], agenda_suggestions: [], top_entities: [] };

let parsed = tryParse(raw);
const parse_ok = !!parsed;
if (!parsed){
  console.error('[NEXO Intelligence] JSON da IA inválido - fallback determinístico.');
  const tr = d.trend_analysis, sm = d.strategic_metrics, st = d.statistics;
  parsed = Object.assign({}, EMPTY, {
    summary: 'Análise automática indisponível neste ciclo. Síntese determinística: ' + st.total_mentions + ' menções, ' + st.sentiment_ratio.negative + '% negativas, Overall ' + sm.overall_intelligence_score + '/100, Risk ' + sm.risk_score + '/100.',
    sentiment_analysis: { overview: 'Derivado de métricas.', trend: tr.sentiment_trend, critical_points: [] },
    themes_rising: tr.themes_rising.map(t => ({ theme: t.tema, reason: 'Crescimento de +' + t.delta + ' menções vs período anterior.', urgency: t.delta >= 5 ? 'high' : 'medium' })),
    themes_falling: tr.themes_falling.map(t => ({ theme: t.tema, reason: 'Queda de ' + t.delta + ' menções.' })),
    insights: ['Overall Intelligence Score: ' + sm.overall_intelligence_score + '/100.', 'Risk Score: ' + sm.risk_score + '/100.']
  });
}
const intelligence = Object.assign({}, EMPTY, parsed);
console.log('[NEXO Intelligence] Parse IA: ' + (parse_ok ? 'OK' : 'FALLBACK'));
return [{ json: Object.assign({}, d, { intelligence, parse_ok }) }];

// === GERAR RELATÓRIO + ALERTAS DETERMINÍSTICOS + SNAPSHOT ===
const d = $input.first().json;
const c = d.campaign, ai = d.intelligence, sm = d.strategic_metrics, st = d.statistics, tr = d.trend_analysis;
const now = new Date().toISOString();
const TH = { risk: 65, crisis: 60, attack: 60, neg_ratio: 0.5, neg_change_pp: 15 };

// Conteúdo do relatório: CONTRATO preservado + novas seções aditivas
const reportContent = {
  summary: ai.summary,
  sentiment_analysis: ai.sentiment_analysis,
  themes_rising: ai.themes_rising,
  themes_falling: ai.themes_falling,
  risks: ai.risks,
  opportunities: ai.opportunities,
  adversary_movements: ai.adversary_movements,
  narrative_changes: ai.narrative_changes,
  crisis_alerts: ai.crisis_alerts,
  insights: ai.insights,
  recommendations: ai.recommendations,
  agenda_suggestions: ai.agenda_suggestions,
  top_entities: ai.top_entities,
  strategic_metrics: sm,
  trend_analysis: tr,
  data_summary: { total_mentions: st.total_mentions, sentiment_ratio: st.sentiment_ratio, risk_score: sm.risk_score / 100, top_themes: d.clusters_themes.slice(0, 10), top_sources: d.clusters_sources.slice(0, 8), period: '24h' },
  ai_parse_ok: d.parse_ok,
  generated_at: now
};

const alerts = [];
const push = a => alerts.push({ campaign_id: c.id, entity_id: a.entity_id || null, type: a.type, title: a.title, description: a.description || '', severity: a.severity || 'medium', source_url: a.source_url || null, metadata: JSON.stringify(a.metadata || { source: 'intelligence_engine' }), status: 'open', read: false, created_at: now });

// Regras determinísticas (independentes da IA)
if (sm.risk_score >= TH.risk) push({ type: 'strategic_risk', title: 'Risk Score elevado (' + sm.risk_score + '/100)', description: 'Indicador de risco acima do limite (' + TH.risk + '). Negatividade em ' + st.sentiment_ratio.negative + '%.', severity: sm.risk_score >= 80 ? 'critical' : 'high', metadata: { risk_score: sm.risk_score, source: 'rule' } });
if (sm.crisis_score >= TH.crisis) push({ type: 'crisis_detected', title: 'Crisis Score elevado (' + sm.crisis_score + '/100)', description: 'Possível crise: pico negativo de alto impacto detectado.', severity: sm.crisis_score >= 80 ? 'critical' : 'high', metadata: { crisis_score: sm.crisis_score, source: 'rule' } });
if (sm.attack_score >= TH.attack) push({ type: 'adversary_movement', title: 'Attack Score elevado (' + sm.attack_score + '/100)', description: 'Atividade adversária acima do limite (' + st.adversary_count + ' menções de adversários, ' + st.adversary_negative + ' negativas).', severity: 'high', metadata: { attack_score: sm.attack_score, source: 'rule' } });
const negRatio = st.total_mentions ? st.sentiment_count.negative / st.total_mentions : 0;
if (negRatio >= TH.neg_ratio) push({ type: 'sentiment_critical', title: 'Sentimento negativo crítico', description: st.sentiment_ratio.negative + '% das menções negativas nas últimas 24h.', severity: negRatio >= 0.6 ? 'critical' : 'high', metadata: { negative_ratio: Number(negRatio.toFixed(3)), source: 'rule' } });
if (tr.has_baseline && tr.negative_change_pp >= TH.neg_change_pp) push({ type: 'negative_trend', title: 'Piora acelerada de sentimento', description: 'Sentimento negativo subiu ' + tr.negative_change_pp + 'pp vs período anterior.', severity: 'high', metadata: { negative_change_pp: tr.negative_change_pp, source: 'rule' } });

// Complemento da IA
